// Fork of "Basic : Voronoi Tracking" by Gijs. https://shadertoy.com/view/WltSz7


// --------------------------------------------------------
// IMAGE (FINAL PASS)
// --------------------------------------------------------
// iChannel0 => Buffer A  (stores particle (pos, vel))
// iChannel1 => Buffer B  (stores nearest site IDs per pixel)
// iChannel2 => Buffer C  (stores secondDist for each site)
// --------------------------------------------------------

// 1) NO redefinition of PARTICLES or SPEED -- they live in Common!
// 2) Derivatives (dFdx/dFdy) are supported by default in WebGL2, 
//    so we skip #extension lines.

#define VERTEX_RADIUS 1.5  // highlight size for corners

//--------------------------------------------------
// HELPER FUNCTIONS
//--------------------------------------------------

// Convert site/particle ID -> pixel coords
ivec2 locFromID(int id)
{
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

// Retrieve (pos, vel) from Buffer A
vec4 getParticle(int id)
{
    return texelFetch(iChannel0, locFromID(id), 0);
}

// Return the 4 candidate site IDs from Buffer B at pixel coords c
ivec4 getClosest4(ivec2 c)
{
    return ivec4(texelFetch(iChannel1, c, 0));
}

// Periodic distance between points a and b
float periodicDist(vec2 a, vec2 b)
{
    vec2 d = a - b;
    d = mod(d + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
    return length(d);
}

// Periodic delta vector
vec2 periodicDelta(vec2 delta)
{
    return mod(delta + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

// For a pixel c, find which site is truly nearest 
int getNearestID(ivec2 c)
{
    ivec4 four = getClosest4(c);
    float bestD = 1e20;
    int   bestI = -1;
    vec2  fc    = vec2(c);

    for (int i=0; i<4; i++)
    {
        int candidateID = four[i];
        vec2 p = getParticle(candidateID).xy;
        float d = periodicDist(fc, p);
        if (d < bestD)
        {
            bestD = d;
            bestI = candidateID;
        }
    }
    return bestI;
}

// Count how many distinct site IDs occur in a 3x3 neighborhood (corner detection)
int countDistinctSites(ivec2 center)
{
    int arr[9];
    int index = 0;
    for(int dy=-1; dy<=1; dy++){
        for(int dx=-1; dx<=1; dx++){
            ivec2 c = center + ivec2(dx, dy);
            // clamp if not wrapping
            c = clamp(c, ivec2(0), ivec2(iResolution.xy)-ivec2(1));
            arr[index++] = getNearestID(c);
        }
    }

    int distinct = 0;
    for(int i=0; i<9; i++){
        bool isNew = true;
        for(int j=0; j<i; j++){
            if(arr[i] == arr[j]){
                isNew = false;
                break;
            }
        }
        if(isNew) distinct++;
    }
    return distinct;
}

// Simple random grey function
float randomGrey(int siteID)
{
    float r = fract(sin(float(siteID) * 78.233) * 43758.5453);
    return 0.85 + 0.1 * r;
}

//--------------------------------------------------
// MAIN
//--------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    //------------------------------------
    // 1) Find nearest site ID for this pixel
    //------------------------------------
    ivec2 pc  = ivec2(fragCoord);
    int   sid = getNearestID(pc);

    //------------------------------------
    // 2) Base color: random grey
    //------------------------------------
    float grey = randomGrey(sid);
    vec4 baseLayer = vec4(vec3(grey), 0.9);

    //------------------------------------
    // 3) Fetch "secondDist" from Buffer C
    //    (distance to the next neighbor)
    //------------------------------------
    float secondDist = texelFetch(iChannel2, locFromID(sid), 0).x;

    //------------------------------------
    // 4) Blue tint based on cell size
    //------------------------------------
    float maxSize   = length(iResolution.xy) * 0.125;
    float sizeRatio = clamp(secondDist / maxSize, 0.0, 1.0);
    vec4 blueLayer  = vec4(0.0, 0.0, 0.8, 0.8 * (1.0 - sizeRatio));
    vec4 color      = mix(baseLayer, blueLayer, blueLayer.a);

    //------------------------------------
    // 5) Centroid highlight
    //------------------------------------
    vec2 sitePos = getParticle(sid).xy;
    float distToCentroid = periodicDist(fragCoord, sitePos);
    color.rgb = mix(color.rgb, vec3(1.0), smoothstep(2.0, 0.0, distToCentroid));

    //------------------------------------
    // 6) Light edge highlight
    //------------------------------------
    float edge = smoothstep(0.0, 1.0, abs(dFdx(grey)) + abs(dFdy(grey)));
    color.rgb  = mix(color.rgb, vec3(0.8), edge);

    //------------------------------------
    // 7) Voronoi corner detection
    //------------------------------------
    int dCount = countDistinctSites(pc);
    if(dCount >= 3)
    {
        // We'll gather the 3 distinct sites from the 4 nearest IDs.
        ivec4 c4 = getClosest4(pc);
        int ids[4] = int[4](c4[0], c4[1], c4[2], c4[3]);

        // Collect up to 3 unique IDs
        int uniqueIDs[3];
        int uniqCount = 0;
        for(int i=0; i<4 && uniqCount<3; i++)
        {
            bool isNew = true;
            for(int j=0; j<uniqCount; j++){
                if(ids[i] == uniqueIDs[j]){
                    isNew = false;
                    break;
                }
            }
            if(isNew){
                uniqueIDs[uniqCount++] = ids[i];
            }
        }
        if(uniqCount < 3)
        {
            // not enough unique sites
            fragColor = color;
            return;
        }

        int id0 = uniqueIDs[0];
        int id1 = uniqueIDs[1];
        int id2 = uniqueIDs[2];

        vec2 A = getParticle(id0).xy;
        vec2 B = getParticle(id1).xy;
        vec2 C = getParticle(id2).xy;

        // Periodic vectors
        vec2 AB = periodicDelta(B - A);
        vec2 AC = periodicDelta(C - A);
        vec2 BA = periodicDelta(A - B);
        vec2 BC = periodicDelta(C - B);
        vec2 CA = periodicDelta(A - C);
        vec2 CB = periodicDelta(B - C);

        // If dot(AB, AC) < 0 => angle at A is obtuse, etc.
        bool obtuseA = dot(AB, AC) < 0.0;
        bool obtuseB = dot(BA, BC) < 0.0;
        bool obtuseC = dot(CA, CB) < 0.0;

        // Compute the actual Voronoi vertex
        vec2 vertexPos;
        if(!obtuseA && !obtuseB && !obtuseC)
        {
            // All angles acute => circumcenter
            vec2 midAB = A + 0.5*AB;
            vec2 midAC = A + 0.5*AC;
            vec2 dirAB = vec2(-AB.y, AB.x);
            vec2 dirAC = vec2(-AC.y, AC.x);

            mat2 M   = mat2(dirAB, -dirAC);
            vec2 rhs = midAC - midAB;
            float det = M[0][0]*M[1][1] - M[0][1]*M[1][0];

            if(abs(det) > 1e-4)
            {
                vec2 t = (1.0/det) * vec2(
                    M[1][1]*rhs.x - M[0][1]*rhs.y,
                    -M[1][0]*rhs.x + M[0][0]*rhs.y
                );
                vertexPos = midAB + t.x * dirAB;
            }
            else
            {
                // fallback: centroid
                vertexPos = (A + B + C) / 3.0;
            }
        }
        else
        {
            // There's an obtuse angle => midpoint of opposite side
            if(obtuseA){
                // corner is mid of BC
                vertexPos = B + 0.5 * BC;
            } else if(obtuseB){
                // corner is mid of AC
                vertexPos = A + 0.5 * AC;
            } else {
                // corner is mid of AB
                vertexPos = A + 0.5 * AB;
            }
        }

        // Extra periodic safety
        vertexPos = mod(vertexPos + 0.5*iResolution.xy, iResolution.xy) 
                    - 0.5*iResolution.xy;

        // Color only near vertex
        float vertexDist = periodicDist(fragCoord, vertexPos);
        if(vertexDist < VERTEX_RADIUS)
        {
            // Like in the snippet: if any angle obtuse => red, else green
            color.rgb = (obtuseA || obtuseB || obtuseC)
                      ? vec3(1.0, 0.0, 0.0) // RED
                      : vec3(0.0, 1.0, 0.0) // GREEN
                      ;
        }
    }

    //------------------------------------
    // Output final color
    //------------------------------------
    fragColor = color;
}

// --------------------------------------------------------
// COMMON TAB
// --------------------------------------------------------
//
// Shadertoy automatically provides iResolution, iTime, iMouse, etc.
// We define constants and a hash function here, shared by all passes.

const int   PARTICLES = 1000; // total number of particles
const float SPEED     = 1.0;  // max speed

// IQ's hashing noise using uintBitsToFloat
float hash(int k)
{
    uint n = uint(k);
    n = (n << 13U) ^ n;
    n = n * (n * n * 15731U + 789221U) + 1376312589U;
    return uintBitsToFloat((n >> 9U) | 0x3f800000U) - 1.0;
}

// --------------------------------------------------------
// BUFFER A
// --------------------------------------------------------
// iChannel0 => Buffer A (feedback/backbuffer)
// iChannel1 => Buffer B

// We assume PARTICLES, SPEED, hash() are defined in Common.

ivec4 getClosest(ivec2 xy)
{
    // read the 4 nearest IDs from Buffer B
    return ivec4(texelFetch(iChannel1, xy, 0));
}

ivec2 locFromID(int id)
{
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec4 getParticle(int id)
{
    // The particle data is stored in Buffer A itself (feedback),
    // so we sample iChannel0 at locFromID(id).
    return texelFetch(iChannel0, locFromID(id), 0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 iFragCoord = ivec2(fragCoord);
    int id = iFragCoord.x + iFragCoord.y * int(iResolution.x);

    // If outside the [0..PARTICLES) range, just copy old data
    if (id >= PARTICLES)
    {
        fragColor = texelFetch(iChannel0, iFragCoord, 0);
        return;
    }

    // Load old position/velocity
    vec4 prev = texelFetch(iChannel0, iFragCoord, 0);
    vec2 pos  = prev.xy;
    vec2 vel  = prev.zw;

    // On first frame, initialize random position
    if (iFrame == 0)
    {
        float h1 = hash(id);
        float h2 = hash(int(h1 * 41343.0));
        pos = vec2(h1, h2) * iResolution.xy;
        vel = vec2(0.0);
    }

    // Accumulate forces
    vec2 force = vec2(0.0);

    // 1) friction
    force -= vel * 0.3;

    // 2) mouse repulsion (if mouse is pressed)
    if (iMouse.z > 0.0)
    {
        vec2 delta = pos - iMouse.xy;
        float dist = length(delta);
        // 1/r^2 repulsion
        force += delta / (dist*dist + 1e-3) * 10.0;
    }

    // 3) repulsion from the 4 nearest neighbors
    ivec4 closestIDs = getClosest(ivec2(pos));
    for (int i = 0; i < 4; i++)
    {
        int cid = closestIDs[i];
        if (cid == id) continue;

        vec2 otherPos = getParticle(cid).xy;
        // handle wrap-around distance
        vec2 delta = pos - otherPos;
        delta = mod(delta + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;

        float dist = length(delta) + 1e-3;
        force += delta / (dist*dist*dist) * 30.0;
    }

    // Integrate forces
    vel += force;

    // Cap speed
    float spd = length(vel);
    if (spd > SPEED)
    {
        vel *= SPEED / spd;
    }

    // Move & wrap
    pos += vel;
    pos = mod(pos, iResolution.xy);

    fragColor = vec4(pos, vel);
}

// --------------------------------------------------------
// BUFFER B
// --------------------------------------------------------
// iChannel0 => Buffer A (positions/vel)
// iChannel1 => Buffer B (backbuffer)

// We rely on a hash(int k) function from the Common tab
// so we do NOT define it locally here.

////////////////////////////////////
// HELPER FUNCTIONS
////////////////////////////////////

// Wrap neighbor coords for a periodic domain
ivec2 wrapCoords(ivec2 c) {
    ivec2 res = ivec2(iResolution.xy);
    return ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
}

// Convert site/particle ID -> pixel coords
ivec2 locFromID(int id) {
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

// Retrieve (pos, vel) from Buffer A for a given site ID
vec4 getParticle(int id) {
    return texelFetch(iChannel0, locFromID(id), 0);
}

// Distance^2 from pixel (fragCoord) to a particle's position
float dist2Particle(int id, vec2 fragCoord) {
    if (id == -1) return 1e20;
    vec2 p = getParticle(id).xy;
    // periodic distance
    vec2 d = p - fragCoord;
    d = mod(d + 0.5 * iResolution.xy, iResolution.xy) - 0.5 * iResolution.xy;
    return dot(d, d);
}

// Insertion sort that also updates duplicates if we find a smaller distance
void insertion_sort(inout ivec4 i, inout vec4 d, int newID, float newDist)
{
    // Check for existing entry
    for (int idx = 0; idx < 4; idx++) {
        if (i[idx] == newID) {
            // If new dist is closer, update & bubble
            if (newDist < d[idx]) {
                d[idx] = newDist;
                for (int k = idx; k > 0 && d[k] < d[k-1]; k--) {
                    // swap
                    int tmpI = i[k];
                    i[k] = i[k-1];
                    i[k-1] = tmpI;

                    float tmpD = d[k];
                    d[k] = d[k-1];
                    d[k-1] = tmpD;
                }
            }
            return;
        }
    }

    // Normal insertion if not a duplicate
    if (newDist < d[0]) {
        i = ivec4(newID, i[0], i[1], i[2]);
        d = vec4(newDist, d[0], d[1], d[2]);
    } else if (newDist < d[1]) {
        i = ivec4(i[0], newID, i[1], i[2]);
        d = vec4(d[0], newDist, d[1], d[2]);
    } else if (newDist < d[2]) {
        i = ivec4(i[0], i[1], newID, i[2]);
        d = vec4(d[0], d[1], newDist, d[2]);
    } else if (newDist < d[3]) {
        i = ivec4(i[0], i[1], i[2], newID);
        d = vec4(d[0], d[1], d[2], newDist);
    }
}

// Returns the 4 IDs stored in the *previous* frame of Buffer B at coords c
ivec4 getClosestPrev(ivec2 c) {
    return ivec4(texelFetch(iChannel1, c, 0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 c = ivec2(fragCoord);

    // We'll build a new set of 4 IDs
    ivec4 newIDs  = ivec4(-1);
    vec4  newDist = vec4(1e20);

    // 1) Gather from a 3x3 block around c
    for (int dy = -1; dy <= 1; dy++){
        for (int dx = -1; dx <= 1; dx++){
            ivec2 cc = wrapCoords(c + ivec2(dx, dy));
            // read the 4 IDs from the previous frame
            ivec4 four = getClosestPrev(cc);
            // insertion-sort them into newIDs (using pixel-center: vec2(c) + 0.5)
            for (int i = 0; i < 4; i++){
                int cand = four[i];
                float d2 = dist2Particle(cand, vec2(c) + 0.5);
                insertion_sort(newIDs, newDist, cand, d2);
            }
        }
    }

    // 2) Add a random candidate to avoid local minima
    //    We call hash(...) from the Common tab
    float h = hash(
        c.x + c.y * int(iResolution.x)
        + iFrame * int(iResolution.x * iResolution.y)
    );
    // If you have "PARTICLES = 500" in Common:
    int rID = int(h * 1000.0);
    float rD2 = dist2Particle(rID, vec2(c) + 0.5);
    insertion_sort(newIDs, newDist, rID, rD2);

    // 3) Output the top 4 IDs
    fragColor = vec4(newIDs);
}

// --------------------------------------------------------
// BUFFER C
// --------------------------------------------------------
// iChannel0 => Buffer A (positions)
// iChannel1 => Buffer B (nearest neighbor IDs)

ivec2 locFromID(int id)
{
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec4 getParticle(int id)
{
    return texelFetch(iChannel0, locFromID(id), 0);
}

// Helper for wrapping distances in a toroidal domain
vec2 periodicDelta(vec2 v)
{
    return mod(v + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

// We'll read from Buffer B at integer coords. 
// Each pixel in B returns 4 site IDs.
ivec4 getClosest4(ivec2 c)
{
    // clamp or wrap c if needed; let's do wrap for full periodic
    ivec2 res = ivec2(iResolution.xy);
    c = ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
    return ivec4(texelFetch(iChannel1, c, 0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 coord = ivec2(fragCoord);
    int id = coord.x + coord.y * int(iResolution.x);

    // If not a valid particle
    if(id >= PARTICLES)
    {
        fragColor = vec4(0.0);
        return;
    }

    // 1) Read this particle's position from Buffer A
    vec4 datA = texelFetch(iChannel0, coord, 0);
    vec2 pos  = datA.xy;

    // 2) Gather multiple pixel neighbors from Buffer B
    //    We'll read a 3x3 block around (floor(pos)), e.g. offsets [-1..1]
    ivec2 base = ivec2(floor(pos));
    float bestDist = 1e20;

    for(int dy=-1; dy<=1; dy++){
        for(int dx=-1; dx<=1; dx++){
            ivec2 sampleCoords = base + ivec2(dx, dy);
            // get 4 IDs from Buffer B
            ivec4 nb = getClosest4(sampleCoords);

            // check each ID, skip self
            for(int i=0; i<4; i++){
                int nid = nb[i];
                if(nid == id) continue; // skip self
                if(nid < 0) continue;   // skip invalid

                // measure distance
                vec2 op = getParticle(nid).xy;
                vec2 d  = periodicDelta(pos - op);
                float dist = length(d);
                if(dist < bestDist){
                    bestDist = dist;
                }
            }
        }
    }

    // 3) Store bestDist in .x
    fragColor = vec4(bestDist, 0.0, 0.0, 1.0);
}
